package com.sgsbarber.model;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.OffsetDateTime;
@Entity @Table(name="business_profile") public class BusinessProfileModel {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String name; private String description; private String phone; private String whatsapp; private String instagram; private String address; private String city;
 private BigDecimal latitude; private BigDecimal longitude; private String logoUrl; @Column(name="created_at",insertable=false,updatable=false) private OffsetDateTime createdAt; @Column(name="updated_at",insertable=false) private OffsetDateTime updatedAt;
 public Long getId(){return id;} public void setId(Long v){id=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getWhatsapp(){return whatsapp;} public void setWhatsapp(String v){whatsapp=v;} public String getInstagram(){return instagram;} public void setInstagram(String v){instagram=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public String getCity(){return city;} public void setCity(String v){city=v;} public BigDecimal getLatitude(){return latitude;} public void setLatitude(BigDecimal v){latitude=v;} public BigDecimal getLongitude(){return longitude;} public void setLongitude(BigDecimal v){longitude=v;} public String getLogoUrl(){return logoUrl;} public void setLogoUrl(String v){logoUrl=v;} public OffsetDateTime getCreatedAt(){return createdAt;} public OffsetDateTime getUpdatedAt(){return updatedAt;}
}
